/** Sign adjudicated host proof input and the receipts generated by attest. */
import { sign, verify, type KeyObject } from "node:crypto";

import { isJsonObject } from "../sync/json-path.js";
import { canonicalText } from "./canonical-json.js";

/** A host input cannot serve as the receipt written by attest. */
type ProofPurpose = "host-proof-import" | "host-proof-receipt";

/** The canonical output covers the phase as well as the evidence body. */
export interface SignedHostProof<Body> {
  readonly purpose: ProofPurpose;
  readonly body: Body;
  readonly signature: string;
}

/** An Ed25519 signature without Base64 padding occupies 86 characters. */
const ENCODED_SIGNATURE = /^[A-Za-z0-9_-]{86}$/u;

/**
 * Sign the canonical body and its intended use with a trusted private key.
 * @param purpose - Whether this is an adjudicated input or an attest receipt
 * @param body - The validated statement
 * @param key - The signer's private Ed25519 key
 * @returns A signed envelope
 * @throws {TypeError} When the supplied key cannot sign this envelope
 */
export function signHostProof<Body extends object>(
  purpose: ProofPurpose,
  body: Body,
  key: KeyObject
): SignedHostProof<Body> {
  if (key.type !== "private" || key.asymmetricKeyType !== "ed25519") {
    throw new TypeError("Host proof signing needs a private Ed25519 key.");
  }
  const payload = { purpose, body };
  const signature = sign(null, Buffer.from(canonicalText(payload)), key);
  return { ...payload, signature: signature.toString("base64url") };
}

/**
 * Return a signed statement only when the authorized signer and phase match.
 * The caller validates the authenticated body's structure and applicability.
 * @param envelope - The untrusted statement and its signature
 * @param purpose - The expected use of the signed statement
 * @param key - The trusted public Ed25519 key for that use
 * @returns The authenticated body, or null when the signature cannot be used
 */
export function verifyHostProof(
  envelope: unknown,
  purpose: ProofPurpose,
  key: KeyObject
): Readonly<Record<string, unknown>> | null {
  if (
    key.type !== "public" ||
    key.asymmetricKeyType !== "ed25519" ||
    !isJsonObject(envelope) ||
    Object.keys(envelope).length !== 3 ||
    envelope.purpose !== purpose ||
    !isJsonObject(envelope.body) ||
    typeof envelope.signature !== "string" ||
    !ENCODED_SIGNATURE.test(envelope.signature)
  )
    return null;

  const signature = Buffer.from(envelope.signature, "base64url");
  if (signature.toString("base64url") !== envelope.signature) return null;
  const message = canonicalText({ purpose, body: envelope.body });
  return verify(null, Buffer.from(message), key, signature)
    ? envelope.body
    : null;
}
